"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["2611"],{6180(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>r,contentTitle:()=>o,toc:()=>l,assets:()=>c});var a=JSON.parse('{"id":"SoftwareEngineering/consistency-cap-theorem","title":"Consistency and the CAP Theorem","description":"Distributed systems face a fundamental trade-off that a single-machine system never has to think about. Understanding it explains why some systems return slightly stale data by design, and why \\"just make it consistent\\" isn\'t always a free choice.","source":"@site/docs/SoftwareEngineering/17-consistency-cap-theorem.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/consistency-cap-theorem","permalink":"/Mindstack/docs/SoftwareEngineering/consistency-cap-theorem","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":17,"frontMatter":{"title":"Consistency and the CAP Theorem","sidebar_label":"Consistency & CAP Theorem","sidebar_position":17},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Scalability Patterns","permalink":"/Mindstack/docs/SoftwareEngineering/scalability-patterns"},"next":{"title":"Testing Strategy","permalink":"/Mindstack/docs/SoftwareEngineering/testing-strategy"}}'),i=t(4848),s=t(8453);let r={title:"Consistency and the CAP Theorem",sidebar_label:"Consistency & CAP Theorem",sidebar_position:17},o="Consistency and the CAP Theorem",c={},l=[{value:"The CAP Theorem",id:"the-cap-theorem",level:2},{value:"Choosing CP or AP Based on the Data",id:"choosing-cp-or-ap-based-on-the-data",level:2},{value:"Eventual Consistency",id:"eventual-consistency",level:2},{value:"Consistency Patterns in Practice",id:"consistency-patterns-in-practice",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"consistency-and-the-cap-theorem",children:"Consistency and the CAP Theorem"})}),"\n",(0,i.jsx)(n.p,{children:'Distributed systems face a fundamental trade-off that a single-machine system never has to think about. Understanding it explains why some systems return slightly stale data by design, and why "just make it consistent" isn\'t always a free choice.'}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"the-cap-theorem",children:"The CAP Theorem"}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"In a distributed system, when a network partition occurs, you must choose between Consistency and Availability \u2014 you cannot have both at that moment."})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"C \u2014 Consistency\n  Every read receives the most recent write, or an error. All nodes\n  see the same data at the same time.\n\nA \u2014 Availability\n  Every request receives a (non-error) response, even if it might\n  not reflect the most recent write.\n\nP \u2014 Partition Tolerance\n  The system continues operating despite network failures between nodes.\n\n              \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n              \u2502                   \u2502\n        \u250C\u2500\u2500\u2500\u2500\u2500\u2524   Pick 2 of 3     \u251C\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n        \u2502     \u2502                   \u2502      \u2502\n        \u25BC     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518      \u25BC\n   CA (Consistency +              CP (Consistency +\n   Availability)                   Partition Tolerance)\n   Only possible WITHOUT           Sacrifice Availability\n   a partition \u2014 not realistic     during a partition \u2014\n   for any real distributed        refuse requests rather\n   system, since networks DO       than risk inconsistent data\n   partition eventually\n\n                    AP (Availability +\n                    Partition Tolerance)\n                    Sacrifice Consistency\n                    during a partition \u2014\n                    keep responding, but\n                    some responses may be stale\n"})}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"The practical takeaway: partition tolerance isn't optional for any real distributed system \u2014 networks fail, packets drop, links go down. So the REAL choice every distributed system architect actually makes is between C and A, specifically during the (hopefully brief, hopefully rare) window when a partition is actually happening."})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'A concrete scenario:\n  Two data centers, connection between them briefly severed.\n  A write arrives at Data Center 1.\n\n  CP choice: Data Center 2 refuses to serve reads/writes for that\n  data until it can confirm consistency with Data Center 1 again \u2014\n  users hitting Data Center 2 see an error rather than risk stale data.\n\n  AP choice: Data Center 2 keeps serving requests using its\n  last-known data \u2014 users hitting Data Center 2 get a fast response,\n  but it might not reflect the write that just landed on Data Center 1.\n\nNeither choice is universally "correct" \u2014 it depends entirely on\nwhat the specific data actually needs.\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"choosing-cp-or-ap-based-on-the-data",children:"Choosing CP or AP Based on the Data"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"CP is usually right for:\n  Financial transactions \u2014 an incorrect balance shown due to a\n  partition is a genuinely serious problem; refusing to serve stale\n  financial data is usually the safer choice than serving it\n  Inventory counts for the LAST unit of a product \u2014 overselling due\n  to stale data has real business/legal consequences\n  Anything where acting on stale data could cause an irreversible,\n  costly mistake\n\nAP is usually right for:\n  Social media feeds \u2014 seeing a slightly-stale feed for a few seconds\n  during a rare network partition is a minor inconvenience, not a\n  real problem, and a broken/error page is a WORSE user experience\n  than a mildly stale one\n  Product catalog browsing \u2014 a price update that takes a few extra\n  seconds to propagate during a partition is far less costly than\n  showing users an error page and losing the sale entirely\n  Most read-heavy, user-facing content where staleness is a minor\n  inconvenience rather than a correctness problem\n\nThis is a genuine judgment call about the SPECIFIC DATA, not a\nsystem-wide, one-time architectural decision \u2014 many real systems make\ndifferent CP/AP choices for different pieces of data within the same\noverall application (your payment processing is CP; your product\nrecommendations feed is AP \u2014 both coexisting in the same product).\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"eventual-consistency",children:"Eventual Consistency"}),"\n",(0,i.jsx)(n.p,{children:"The practical, everyday form the AP choice takes: the system guarantees that IF no new updates occur, all replicas will EVENTUALLY converge to the same value \u2014 but at any given instant, different nodes might briefly disagree."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"   Write \"balance = 100\" to Node A\n        \u2502\n        \u25BC\n   Node A: balance = 100    (immediately)\n   Node B: balance = 90     (hasn't received the update yet)\n   Node C: balance = 90     (hasn't received the update yet)\n\n        \u2502  (a brief propagation delay \u2014 milliseconds, typically)\n        \u25BC\n\n   Node A: balance = 100\n   Node B: balance = 100    (now converged)\n   Node C: balance = 100    (now converged)\n"})}),"\n",(0,i.jsx)(n.p,{children:"This is exactly the mechanism behind read replica lag (file 16), Redis pub/sub delivery, and most NoSQL databases' default consistency model (file 14) \u2014 it's not a bug or a corner case, it's the deliberate, documented trade-off those systems make in exchange for availability and performance."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Different flavors of eventual consistency, roughly ordered from\nweakest to strongest guarantee:\n\n  Eventual consistency (weakest) \u2014 will converge EVENTUALLY, no\n    bound on how long\n  Read-your-writes consistency \u2014 a client is guaranteed to see ITS\n    OWN writes immediately, even if other clients might briefly see\n    stale data (commonly implemented by routing a client's reads to\n    the primary for a brief window right after that client's own write)\n  Monotonic reads \u2014 once a client has seen a value, it will never\n    see an OLDER value on a subsequent read (prevents the confusing\n    experience of data appearing to \"go backward in time\")\n  Strong consistency (the CP choice) \u2014 every read reflects the most\n    recent write, globally, immediately\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"consistency-patterns-in-practice",children:"Consistency Patterns in Practice"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'Financial ledger:                     Strong consistency (CP) \u2014\n                                      correctness matters more than\n                                      availability during a rare partition\n\nShopping cart:                        Often eventual consistency (AP)\n                                      is acceptable \u2014 briefly seeing a\n                                      slightly stale cart is a minor\n                                      inconvenience, not a correctness\n                                      problem, and losing availability\n                                      during checkout is worse for\n                                      the business\n\nInventory count during checkout:      Often needs strong consistency\n                                      specifically at the moment of\n                                      SALE (to avoid overselling the\n                                      last unit), even if the general\n                                      "items in stock" DISPLAY\n                                      elsewhere in the app can be\n                                      eventually consistent\n\nSocial media likes/comments count:    Eventual consistency (AP) \u2014\n                                      an exact real-time count\n                                      rarely matters; availability\n                                      and speed matter far more\n'})}),"\n",(0,i.jsx)(n.p,{children:'Notice the inventory example: even within ONE feature (an e-commerce product), different parts of the SAME data can reasonably use different consistency models \u2014 the number shown on a browsing page can be eventually consistent, while the actual decrement at the moment of purchase needs strong consistency to prevent overselling. This granular, per-operation thinking is more realistic than a single system-wide "we are a CP system" or "we are an AP system" declaration.'}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Treat CAP as a per-piece-of-data decision, not a single system-wide architectural stance \u2014 most real systems mix CP and AP choices across different data, based on what each specific piece of data actually needs."}),"\n",(0,i.jsx)(n.li,{children:"When evaluating a new database or messaging technology, explicitly check which consistency model it defaults to and whether that matches your data's actual needs \u2014 this is a common source of surprising production bugs when the default doesn't match expectations."}),"\n",(0,i.jsx)(n.li,{children:'"Read-your-writes" consistency is often what users actually expect and need, even in an otherwise eventually-consistent system \u2014 a user who just submitted a form generally expects to immediately see their own change reflected, even if OTHER users seeing it a moment later is perfectly fine.'}),"\n",(0,i.jsx)(n.li,{children:"Don't default to strong consistency everywhere \"to be safe\" \u2014 it has a real availability and performance cost, and applying it to data that doesn't need it (a social media like count) is an unnecessary trade-off."}),"\n"]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"CAP theorem: during a network partition (which will eventually happen in any real distributed system), you must choose between Consistency (refuse stale reads) and Availability (keep serving, possibly-stale reads) \u2014 partition tolerance itself isn't optional."}),"\n",(0,i.jsx)(n.li,{children:"Choose CP for data where acting on stale information causes real harm (financial transactions, inventory at the moment of sale); choose AP for data where brief staleness is a minor inconvenience (feeds, browsing views, counts)."}),"\n",(0,i.jsx)(n.li,{children:"Eventual consistency is the everyday, practical form of the AP choice \u2014 replicas converge over time, not instantly; this underlies read replica lag, most NoSQL defaults, and pub/sub delivery."}),"\n",(0,i.jsx)(n.li,{children:"Stronger consistency variants (read-your-writes, monotonic reads) sit between full eventual consistency and full strong consistency, and often match what users actually expect better than either extreme."}),"\n",(0,i.jsx)(n.li,{children:"Treat CAP/consistency choices per data type, not as one system-wide declaration \u2014 the same application can and often should mix CP and AP for different pieces of data based on their actual correctness requirements."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var a=t(6540);let i={},s=a.createContext(i);function r(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);